package io.scenariomesh.scheduler; import io.scenariomesh.core.Domain.*;import java.util.*;
public final class ResourceLedger {private final Map<String,Integer> capacity;private final Map<String,Integer> used=new HashMap<>();public ResourceLedger(Map<String,Integer> capacity){this.capacity=Map.copyOf(capacity);}public synchronized boolean canAcquire(List<ResourceRequirement> r){return r.stream().allMatch(x->used.getOrDefault(x.name(),0)+x.units()<=capacity.getOrDefault(x.name(),0));}public synchronized Lease acquire(List<ResourceRequirement> r){if(!canAcquire(r))throw new IllegalStateException("Resources unavailable");r.forEach(x->used.merge(x.name(),x.units(),Integer::sum));return new Lease(this,List.copyOf(r));}private synchronized void release(List<ResourceRequirement> r){r.forEach(x->used.compute(x.name(),(k,v)->v==null?0:Math.max(0,v-x.units())));}public static final class Lease implements AutoCloseable{private final ResourceLedger l;private final List<ResourceRequirement> r;private boolean closed;Lease(ResourceLedger l,List<ResourceRequirement> r){this.l=l;this.r=r;}public synchronized void close(){if(!closed){l.release(r);closed=true;}}}}
